WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
CREATE TABLE fleet_org (org_id NUMBER PRIMARY KEY, company_name VARCHAR2(150) NOT NULL, tax_id VARCHAR2(50) NOT NULL UNIQUE, credit_line_limit NUMBER DEFAULT 0, current_balance NUMBER DEFAULT 0);
CREATE TABLE substation (substation_id NUMBER PRIMARY KEY, name VARCHAR2(100) NOT NULL, code VARCHAR2(30) UNIQUE, region_code VARCHAR2(20), location VARCHAR2(250), max_grid_capacity_kw NUMBER NOT NULL CHECK (max_grid_capacity_kw>0), base_load_kw NUMBER DEFAULT 0, capacity_limit_pct NUMBER DEFAULT 90, operational_status VARCHAR2(20) DEFAULT 'operational', load_source VARCHAR2(20) DEFAULT 'estimated', constraints_note VARCHAR2(1000));
CREATE TABLE charging_station (station_id NUMBER PRIMARY KEY, substation_id NUMBER NOT NULL REFERENCES substation, org_id NUMBER REFERENCES fleet_org, station_name VARCHAR2(100) NOT NULL, street_address VARCHAR2(255) NOT NULL, city VARCHAR2(100) NOT NULL, status VARCHAR2(20) DEFAULT 'ACTIVE', timezone VARCHAR2(64) DEFAULT 'Asia/Kolkata');
CREATE TABLE charger_bay (bay_id NUMBER PRIMARY KEY, station_id NUMBER NOT NULL REFERENCES charging_station, bay_number NUMBER NOT NULL, plug_type VARCHAR2(20) NOT NULL, max_kw_output NUMBER NOT NULL CHECK (max_kw_output>0), is_operational NUMBER(1) DEFAULT 1 CHECK(is_operational IN (0,1)), UNIQUE(station_id,bay_number));
CREATE TABLE tariff_plan (tariff_id NUMBER PRIMARY KEY, station_id NUMBER NOT NULL REFERENCES charging_station, plan_name VARCHAR2(50) NOT NULL, start_hour NUMBER NOT NULL, end_hour NUMBER NOT NULL, base_rate_per_kwh NUMBER NOT NULL, idle_fee_per_min NUMBER DEFAULT 0, currency VARCHAR2(3) DEFAULT 'INR', tax_pct NUMBER DEFAULT 0, service_fee NUMBER DEFAULT 0, discount_amount NUMBER DEFAULT 0, active NUMBER(1) DEFAULT 1, CHECK(start_hour>=0 AND end_hour<=24 AND end_hour>start_hour));
CREATE TABLE app_user (user_id NUMBER PRIMARY KEY, org_id NUMBER REFERENCES fleet_org, full_name VARCHAR2(100) NOT NULL, email VARCHAR2(150) NOT NULL UNIQUE, phone VARCHAR2(25), role VARCHAR2(20) DEFAULT 'customer' CHECK (role IN ('customer','manager')));
CREATE TABLE vehicle (vehicle_id NUMBER PRIMARY KEY, vin VARCHAR2(17) UNIQUE, org_id NUMBER REFERENCES fleet_org, user_id NUMBER NOT NULL REFERENCES app_user, license_plate VARCHAR2(20) NOT NULL, make VARCHAR2(80), model VARCHAR2(80), vehicle_type VARCHAR2(30), connector_types VARCHAR2(200), battery_capacity_kwh NUMBER, max_charge_rate_kw NUMBER, current_soc_pct NUMBER DEFAULT 50, ownership_type VARCHAR2(20), archived_at TIMESTAMP);
CREATE TABLE fleet_mission (mission_id NUMBER PRIMARY KEY, vehicle_id NUMBER REFERENCES vehicle, fleet_org_id NUMBER REFERENCES fleet_org, driver_id NUMBER REFERENCES app_user, mission_label VARCHAR2(150), departure_time TIMESTAMP NOT NULL, target_soc_pct NUMBER NOT NULL, route_distance_km NUMBER, priority_level NUMBER DEFAULT 1, status VARCHAR2(20) DEFAULT 'scheduled');
CREATE TABLE reservation (reservation_id NUMBER PRIMARY KEY, bay_id NUMBER NOT NULL REFERENCES charger_bay, vehicle_id NUMBER REFERENCES vehicle, user_id NUMBER NOT NULL REFERENCES app_user, start_time TIMESTAMP NOT NULL, end_time TIMESTAMP NOT NULL, status VARCHAR2(20) DEFAULT 'confirmed', CHECK(end_time>start_time));
CREATE TABLE charging_session (session_id NUMBER PRIMARY KEY, bay_id NUMBER NOT NULL REFERENCES charger_bay, vehicle_id NUMBER REFERENCES vehicle, user_id NUMBER NOT NULL REFERENCES app_user, reservation_id NUMBER UNIQUE REFERENCES reservation, start_time TIMESTAMP, end_time TIMESTAMP, scheduled_at TIMESTAMP, allocated_kw NUMBER DEFAULT 0, energy_delivered_kwh NUMBER DEFAULT 0, idle_minutes NUMBER DEFAULT 0, status VARCHAR2(20) DEFAULT 'scheduled', meter_source VARCHAR2(20), initial_meter_kwh NUMBER, final_meter_kwh NUMBER, simulation_elapsed_seconds NUMBER DEFAULT 0);
CREATE TABLE maintenance_log (log_id NUMBER PRIMARY KEY, bay_id NUMBER NOT NULL REFERENCES charger_bay, technician_id NUMBER REFERENCES app_user, issue_reported VARCHAR2(500) NOT NULL, reported_at TIMESTAMP DEFAULT SYSTIMESTAMP, resolved_at TIMESTAMP, repair_status VARCHAR2(20) DEFAULT 'OPEN');
CREATE TABLE invoice (invoice_id NUMBER PRIMARY KEY, session_id NUMBER NOT NULL UNIQUE REFERENCES charging_session, invoice_number VARCHAR2(40), energy_charge NUMBER DEFAULT 0, idle_penalty_charge NUMBER DEFAULT 0, tax_amount NUMBER DEFAULT 0, service_fee NUMBER DEFAULT 0, discount_amount NUMBER DEFAULT 0, total_amount NUMBER DEFAULT 0, currency VARCHAR2(3) DEFAULT 'INR', status VARCHAR2(20) DEFAULT 'pending');
CREATE TABLE payment (payment_id NUMBER PRIMARY KEY, invoice_id NUMBER NOT NULL REFERENCES invoice, payment_method VARCHAR2(20), paid_amount NUMBER, transaction_ref VARCHAR2(100), settled_at TIMESTAMP, status VARCHAR2(20), currency VARCHAR2(3) DEFAULT 'INR', created_at TIMESTAMP DEFAULT SYSTIMESTAMP);
CREATE TABLE reservation_checkout (checkout_id NUMBER PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES app_user, vehicle_id NUMBER NOT NULL REFERENCES vehicle, bay_id NUMBER NOT NULL REFERENCES charger_bay, start_time TIMESTAMP NOT NULL, end_time TIMESTAMP NOT NULL, reservation_id NUMBER UNIQUE REFERENCES reservation, status VARCHAR2(20) DEFAULT 'pending', amount NUMBER DEFAULT 0, currency VARCHAR2(3) DEFAULT 'INR', transaction_ref VARCHAR2(100), created_at TIMESTAMP DEFAULT SYSTIMESTAMP);
CREATE SEQUENCE gridsync_seq START WITH 100 INCREMENT BY 1;
